#include <iostream>
#include <locale>

int main() {
    // Create a locale object with the default environment locale
    std::locale loc;
    // Retrieve the numpunct facet (used for number punctuation formatting)
    const std::numpunct<char>& np = std::use_facet<std::numpunct<char>>(loc);
    // Output the decimal point character for the locale
    std::cout << "Decimal point: " << np.decimal_point() << std::endl;
    return 0;
}
